# The Xcode and simulator lookup of the Xcode tasks. Import it after helpers,
# with the import preamble of a task. Each function takes the name of the
# calling task first, for its messages.
#
# A repository can set each of these values in the [env] of
# .config/mise/conf.d/zz-repo/mise.<env>.toml. Without a value, require_xcode
# finds it:
#   XCODE_VERSION       the selected Xcode (xcodebuild -version)
#   SIMULATOR_PLATFORM  iOS
#   SIMULATOR_OS        the newest available iOS runtime
#   SIMULATOR_DEVICE    the available iPhone of that runtime with the highest
#                       model number and no other word in its name, for
#                       example "iPhone 17"

import glob
import os
import re
import subprocess
import sys

import helpers


def _number(text):
  """Return the leading integer of text, or 0, as awk does with text + 0."""
  match = re.match(r"[ \t]*([-+]?[0-9]+)", text)
  return int(match.group(1)) if match else 0


def _newer(a, b):
  """Compare two dotted versions; true when a is newer than b."""
  x = a.split(".")
  y = b.split(".")
  for i in range(max(len(x), len(y))):
    xi = _number(x[i]) if i < len(x) else 0
    yi = _number(y[i]) if i < len(y) else 0
    if xi != yi:
      return xi > yi
  return False


def _xcode_simulator():
  """Return the (os, device) of the default simulator, or None."""
  try:
    result = subprocess.run(
      ["xcrun", "simctl", "list", "devices", "available"],
      check=False,
      stdout=subprocess.PIPE,
      stderr=subprocess.DEVNULL,
      text=True,
      errors="replace",
    )
    output = result.stdout
  except OSError:
    output = ""
  runtime = ""
  best_os = ""
  best = 0
  device = ""
  for line in output.splitlines():
    if line.startswith("-- "):
      fields = line.split()
      runtime = fields[2] if len(fields) > 2 and fields[1] == "iOS" else ""
      continue
    if runtime == "":
      continue
    # "    iPhone 17 (<udid>) (Shutdown)", with " (<os>)" after the name in an
    # older runtime.
    name = line.strip(" ")
    name = re.sub(r" \([^()]*\) \([^()]*\)$", "", name, count=1)
    name = re.sub(r" \([0-9.]+\)$", "", name, count=1)
    if not re.fullmatch(r"iPhone [0-9]+", name):
      continue
    model = _number(name[7:])
    if best_os == "" or _newer(runtime, best_os):
      best_os = runtime
      best = 0
    if runtime == best_os and model > best:
      best = model
      device = name
  if device == "":
    return None
  return best_os, device


def require_xcode(task):
  """Fail when no Xcode is selected, or when XCODE_VERSION is not the selected
  Xcode. Set XCODE_VERSION and the SIMULATOR_* values that the repository does
  not set in os.environ, and return each of these names that has a value."""
  # Do not test for xcodebuild: each Mac has a /usr/bin/xcodebuild stub.
  try:
    result = subprocess.run(
      ["xcodebuild", "-version"],
      check=False,
      stdout=subprocess.PIPE,
      stderr=subprocess.DEVNULL,
      text=True,
      errors="replace",
    )
    failed = result.returncode != 0
  except OSError:
    failed = True
  if failed:
    helpers.print_error(f"{task}: no Xcode is selected - xcodebuild -version failed")
    helpers.print_info("Install Xcode, then select it: sudo xcode-select -s /Applications/Xcode.app")
    sys.exit(1)
  lines = result.stdout.splitlines()
  fields = lines[0].split() if lines else []
  version = fields[1] if len(fields) > 1 else ""
  wanted = os.environ.get("XCODE_VERSION", "")
  if wanted and wanted != version:
    helpers.print_error(f"{task}: this repository needs Xcode {wanted}, but Xcode {version} is selected")
    helpers.print_info(f"Select Xcode {wanted} with xcode-select -s, or set DEVELOPER_DIR to it")
    sys.exit(1)
  os.environ["XCODE_VERSION"] = version
  os.environ["SIMULATOR_PLATFORM"] = os.environ.get("SIMULATOR_PLATFORM") or "iOS"
  if os.environ["SIMULATOR_PLATFORM"] == "iOS" and not (
    os.environ.get("SIMULATOR_OS") and os.environ.get("SIMULATOR_DEVICE")
  ):
    found = _xcode_simulator()
    if found is None:
      helpers.print_error(f"{task}: no available iPhone simulator found")
      helpers.print_info(
        "Install an iOS runtime in Xcode, or set SIMULATOR_OS and SIMULATOR_DEVICE in the [env] of "
        ".config/mise/conf.d/zz-repo/mise.<env>.toml"
      )
      sys.exit(1)
    os.environ["SIMULATOR_OS"] = os.environ.get("SIMULATOR_OS") or found[0]
    os.environ["SIMULATOR_DEVICE"] = os.environ.get("SIMULATOR_DEVICE") or found[1]
  names = ("XCODE_VERSION", "SIMULATOR_PLATFORM", "SIMULATOR_OS", "SIMULATOR_DEVICE")
  return {name: os.environ[name] for name in names if os.environ.get(name)}


def find_xcodeproj(task):
  """Return the one *.xcodeproj at the root of the repository. The messages go
  to stderr."""
  projects = [project for project in sorted(glob.glob("*.xcodeproj")) if os.path.isdir(project)]
  if not projects:
    helpers.print_error(f"{task}: no *.xcodeproj at the root of the repository", file=sys.stderr)
    helpers.print_info(
      "Make the project of the app in Xcode, save it at the root of the repository, and commit it",
      file=sys.stderr,
    )
    sys.exit(1)
  if len(projects) > 1:
    helpers.print_error(f"{task}: the root has more than one *.xcodeproj: {' '.join(projects)}", file=sys.stderr)
    helpers.print_info("Keep one project at the root", file=sys.stderr)
    sys.exit(1)
  return projects[0]
